import Image from "next/image";
import { cn } from "@/lib/utils";

/**
 * Round logo badge: the crowned cake cropped from the real logo, on its dark
 * ground, with a hairline gold ring. Source: public/brand/badge-*.webp
 * (generated by scripts/prep-brand.mjs — never ship the 2 MB master).
 */
export function BrandBadge({
  size = 40,
  className,
  alt = "",
}: {
  /** Rendered size in px. */
  size?: number;
  className?: string;
  /** Empty when the badge sits next to the written brand name. */
  alt?: string;
}) {
  return (
    <span
      className={cn(
        "relative inline-block shrink-0 overflow-hidden rounded-full bg-gp-ink ring-1 ring-gp-gold/70",
        className
      )}
      style={{ width: size, height: size }}
    >
      <Image
        src={size > 96 ? "/brand/badge-384.webp" : "/brand/badge-192.webp"}
        alt={alt}
        width={size}
        height={size}
        loading="eager"
        className="h-full w-full object-cover"
      />
    </span>
  );
}

/** Aspect ratio of public/brand/wordmark-mask.webp (819 × 251). */
export const WORDMARK_RATIO = 819 / 251;

/**
 * The logo's script wordmark "Gateaux Patience", painted in any colour
 * (currentColor) through a CSS mask. Size it with a width class; height follows.
 */
export function BrandWordmark({
  className,
  label = "Gateaux Patience",
  decorative = false,
}: {
  className?: string;
  label?: string;
  decorative?: boolean;
}) {
  return (
    <span
      role={decorative ? undefined : "img"}
      aria-label={decorative ? undefined : label}
      aria-hidden={decorative || undefined}
      className={cn("block bg-current", className)}
      style={{
        aspectRatio: `${WORDMARK_RATIO}`,
        WebkitMaskImage: "url(/brand/wordmark-mask.webp)",
        maskImage: "url(/brand/wordmark-mask.webp)",
        WebkitMaskSize: "100% 100%",
        maskSize: "100% 100%",
        WebkitMaskRepeat: "no-repeat",
        maskRepeat: "no-repeat",
      }}
    />
  );
}
